// org.site.changeStandard — E1 AC3 as changed by D-25: staff change a site's standard both ways; the Project
// ID stays. Generated by `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, runAsOwner, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  NotFound,
  openTestKernel,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { changeStandard } from '../commands/change-standard.ts';
import { createClient } from '../commands/create-client.ts';
import { createSite } from '../commands/create-site.ts';

const director = aStaffActor({ roles: ['director'] });
const other = aStaffActor();
const standardOf = (siteId: string, standard: 'L' | 'S') =>
  countRows(testDb.url, 'site WHERE id = $1 AND standard = $2', [siteId, standard]);
let testDb: TestDatabase;
let t: TestKernel;
let siteId: string;
let projectId: string;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(director, createClient.permission, createSite.permission, changeStandard.permission);
  const owner = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTC', name: 'Client C' },
    'test',
  );
  const place = { countryCode: 'PT', cityCode: 'LIS', cityName: 'Lisbon', name: 'Site 001', standard: 'S' };
  ({ id: siteId, projectId } = await t.kernel.execute(
    createSite,
    director,
    { clientId: owner.id, ...place },
    'test',
  ));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.site.changeStandard', () => {
  it('refuses an actor without the permission', async () => {
    await expect(
      t.kernel.execute(changeStandard, other, { siteId, standard: 'L' }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
  });

  it('refuses a standard other than L or S', async () => {
    await expect(
      t.kernel.execute(changeStandard, director, { siteId, standard: 'M' }, 'test'),
    ).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('changes S → L and back L → S, keeping the Project ID, each change audited', async () => {
    expect(await t.kernel.execute(changeStandard, director, { siteId, standard: 'L' }, 'test')).toEqual({
      projectId,
      standard: 'L',
    });
    expect(await standardOf(siteId, 'L')).toBe(1);
    expect(await t.kernel.execute(changeStandard, director, { siteId, standard: 'S' }, 'test')).toEqual({
      projectId,
      standard: 'S',
    });
    expect(await standardOf(siteId, 'S')).toBe(1);
    expect(
      await countRows(
        testDb.url,
        `audit_event WHERE command = 'org.site.changeStandard' AND object_id = $1 AND before->>'standard' = 'L' AND after->>'standard' = 'S'`,
        [siteId],
      ),
    ).toBe(1);
    expect(await countRows(testDb.url, `outbox WHERE event_type = 'org.site.standardChanged'`)).toBe(2);
  });

  it('refuses a change to the standard the site already has', async () => {
    await expect(
      t.kernel.execute(changeStandard, director, { siteId, standard: 'S' }, 'test'),
    ).rejects.toBeInstanceOf(Conflict);
  });

  it('refuses an unknown or archived site', async () => {
    await expect(
      t.kernel.execute(changeStandard, director, { siteId: randomUUID(), standard: 'L' }, 'test'),
    ).rejects.toBeInstanceOf(NotFound);
    await runAsOwner(testDb.url, 'UPDATE site SET archived_at = now() WHERE id = $1', [siteId]);
    await expect(
      t.kernel.execute(changeStandard, director, { siteId, standard: 'L' }, 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });
});
